import {useQuery, useQueryClient} from "@tanstack/react-query";
import {getMyDevices} from "~/api/base/userApi";

export const useDevices = () => {
    const queryClient = useQueryClient();

    // 使用 useQuery 获取数据
    const {data: devices = [], isLoading, error} = useQuery({
        queryKey: ['devices'], // 唯一标识符
        queryFn: getMyDevices,  // 数据获取函数
        staleTime: 30 * 1000   // 缓存30秒
    })

    // 全局刷新函数
    const refreshDevices = () => queryClient.invalidateQueries({
        queryKey: ['devices']
    })

    // 计算派生状态
    const deviceStats = {
        used: devices.filter(device => device.status === 1).length,
        total: devices.length,
        onlineCount: devices.filter(device => device.status === 1).length,
        offlineCount: devices.filter(device => device.status === 0).length
    };

    return {devices, isLoading, error, refreshDevices, deviceStats}
}

// 2. 在组件中使用
function DeviceManager() {
    const {devices, isLoading, refreshDevices, deviceStats} = useDevices();

    if (isLoading) return <div>加载中...</div>;

    return (
        <div>
            <div>在线设备: {deviceStats.onlineCount}</div>
            <button onClick={refreshDevices}>刷新设备</button>
            {devices.map(device => (
                <div key={device.id}>{device.name}</div>
            ))}
        </div>
    );
}`})}),o.jsxs("div",{className:Y.explanationPoints,children:[o.jsx("h5",{children:"代码解析："}),o.jsxs("ul",{children:[o.jsxs("li",{children:[o.jsx("strong",{children:"全局缓存"}),"：通过 queryKey 建立全局缓存，所有使用相同 key 的组件共享数据"]}),o.jsxs("li",{children:[o.jsx("strong",{children:"自动状态管理"}),"：isLoading、error 状态自动管理，无需手动处理"]}),o.jsxs("li",{children:[o.jsx("strong",{children:"全局刷新"}),"：通过 invalidateQueries 实现一处刷新，全局同步"]}),o.jsxs("li",{children:[o.jsx("strong",{children:"派生状态"}),"：在 hook 中计算派生状态，组件直接使用"]}),o.jsxs("li",{children:[o.jsx("strong",{children:"缓存策略"}),"：通过 staleTime 控制数据新鲜度，减少不必要的请求"]})]})]})]})]}),o.jsxs("div",{ref:C=>{x.current[1]=C},className:Y.demoCard,children:[o.jsxs("div",{className:Y.demoHeader,children:[o.jsx("h3",{className:Y.demoTitle,children:"为什么我不用 Zustand 了？"}),o.jsx("button",{className:Y.infoButton,onClick:()=>k(2),children:o.jsx(Ln,{})})]}),o.jsxs("div",{className:Y.comparisonContent,children:[o.jsxs("div",{className:Y.comparisonItem,children:[o.jsxs("div",{className:Y.comparisonLabel,children:[o.jsx(cv,{className:Y.warningIcon}),"以前用 Zustand 的时候"]}),o.jsxs("ul",{className:Y.comparisonList,children:[o.jsx("li",{children:"天天手写 loading、error 状态，累死了"}),o.jsx("li",{children:"接口调用要手动触发，忘了就出 bug"}),o.jsx("li",{children:"缓存？自己写吧，复杂得要命"}),o.jsx("li",{children:"多个页面同步数据？各种监听器飞起"})]})]}),o.jsxs("div",{className:Y.comparisonItem,children:[o.jsxs("div",{className:Y.comparisonLabel,children:[o.jsx(gm,{className:Y.successIcon}),"现在用 React Query"]}),o.jsxs("ul",{className:Y.comparisonList,children:[o.jsx("li",{children:"嗨，这些状态都自动给你管好了"}),o.jsx("li",{children:"缓存、刷新全部自动，不用操心"}),o.jsx("li",{children:"invalidateQueries 一行搞定全局刷新"}),o.jsx("li",{children:"多个页面自动同步，神了！"})]})]})]}),i===2&&o.jsxs("div",{className:Y.explanationPanel,children:[o.jsx("h4",{className:Y.explanationTitle,children:"经验分享：为什么我不用 Zustand 了"}),o.jsx("div",{className:Y.codeBlock,children:o.jsx("pre",{className:Y.codeContent,children:`// 以前用 Zustand 的时候，干什么都要自己来
import create from 'zustand';
import {getMyDevices} from "~/api/base/userApi";

const useDeviceStore = create((set, get) => ({
    devices: [],
    isLoading: false,
    error: null,

    // loading、error 状态要自己管理，烦死了
    fetchDevices: async () => {
        set({isLoading: true, error: null});
        try {
            const devices = await getMyDevices();
            set({devices, isLoading: false});
        } catch (error) {
            set({error: error.message, isLoading: false});
        }
    },

    // 刷新要自己写，多个页面同步还要考虑各种情况
    refreshDevices: () => {
        get().fetchDevices(); // 这样只能刷新当前组件
    }
}));

// 现在用 React Query，真的香爆了！
export const useDevices = () => {
    const queryClient = useQueryClient();

    // 一行代码搞定所有状态，自动缓存、自动重试
    const {data: devices = [], isLoading, error} = useQuery({
        queryKey: ['devices'], // 全局唯一 key，所有组件都共享
        queryFn: getMyDevices,
        staleTime: 30 * 1000   // 30秒内不重复请求
    })

    // 全局刷新真的就一行代码！所有用这个 key 的地方都会更新
    const refreshDevices = () => queryClient.invalidateQueries({
        queryKey: ['devices']
    })

    return {devices, isLoading, error, refreshDevices}
}`})}),o.jsxs("div",{className:Y.explanationPoints,children:[o.jsx("h5",{children:"总结一下为什么香："}),o.jsxs("ul",{children:[o.jsxs("li",{children:[o.jsx("strong",{children:"代码量狂减"}),"：以前 50 行代码，现在 10 行搞定"]}),o.jsxs("li",{children:[o.jsx("strong",{children:"不用操心的事"}),"：loading、error、缓存全部自动处理"]}),o.jsxs("li",{children:[o.jsx("strong",{children:"真正的全局同步"}),"：一处刷新，全站更新，不用写各种监听器"]}),o.jsxs("li",{children:[o.jsx("strong",{children:"开发效率爆炖"}),"：专注业务逻辑，不用纠结状态管理"]}),o.jsxs("li",{children:[o.jsx("strong",{children:"性能优化全家桶"}),"：缓存、去重、重试、轮询，什么都有"]})]})]})]})]})]})]}),o.jsxs("section",{className:Y.section,children:[o.jsxs("div",{className:Y.sectionHeader,ref:C=>{m.current[3]=C},children:[o.jsx("h2",{className:Y.sectionTitle,children:"开发时常用的参数配置"}),o.jsx("p",{className:Y.sectionSubtitle,children:"这些参数真的太好用了，不知道就亏大了"})]}),o.jsxs("div",{className:Y.featuresGrid,children:[o.jsxs("div",{ref:C=>{y.current[0]=C},className:Y.featureCard,children:[o.jsx("h3",{className:Y.featureTitle,children:"enabled - 控制是否执行"}),o.jsx("div",{className:Y.codeBlock,children:o.jsx("pre",{className:Y.codeContent,children:`// 有时候你不想一上来就请求接口，比如用户没登录的时候
