const buildQueryParams = () => {
    const params = {
        page: pagination.current,
        size: pagination.pageSize,
        task_type: '养号任务',
    };

    if (selectedDevice) {
        params.device_ids = selectedDevice;
    }

    if (selectedStatus) {
        const statusMap = {
            'waiting': '等待执行',
            'running': '执行中',
            'success': '执行成功',
            'failed': '执行失败'
        };
        params.status = statusMap[selectedStatus];
    }

    return params;
}

// 关键：把分页和筛选条件都放到 queryKey 里
const {data: taskListData, isLoading} = useQuery({
    queryKey: ['taskList', pagination.current, pagination.pageSize, selectedDevice, selectedStatus],
    queryFn: () => getTaskList(buildQueryParams()),
    refetchInterval: 5000, // 还能轮询刷新
});`})}),o.jsx("div",{className:Y.codeExplanation,children:o.jsxs("p",{children:[o.jsx("strong",{children:"核心思路："})," 把分页、筛选条件都放到 queryKey 里，参数一变就自动重新请求，不用手动管理。"]})})]}),o.jsxs("div",{ref:C=>{y.current[3]=C},className:Y.featureCard,children:[o.jsx("h3",{className:Y.featureTitle,children:"useMutation - 处理增删改"}),o.jsx("div",{className:Y.codeBlock,children:o.jsx("pre",{className:Y.codeContent,children:`// 查询用 useQuery，增删改用 useMutation
